using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Markup;
using Microsoft.UI.Xaml.Media;

namespace Wintor.App.Icons;

/// <summary>
/// Creates Hugeicons icons. Geometry comes from <see cref="HugeIconData"/>, generated by
/// tools/Wintor.IconTool from the SVGs in Assets/Icons. Icons are filled with Foreground,
/// so they follow the theme like any built-in icon.
/// </summary>
public static class HugeIcons
{
    /// <summary>The grid Hugeicons are drawn on.</summary>
    private const double SourceSize = 24;

    public static PathIcon Create(HugeIconKind kind, double size = 16)
    {
        // A Geometry can only belong to one element, so every icon gets its own parsed copy.
        var geometry = (Geometry)XamlBindingHelper.ConvertValue(typeof(Geometry), HugeIconData.Get(kind));
        double scale = size / SourceSize;
        if (scale != 1)
        {
            // At exactly 1 a ScaleTransform made the icon disappear, so the native 24 px size gets none.
            geometry.Transform = new ScaleTransform { ScaleX = scale, ScaleY = scale };
        }

        // A fixed square keeps every icon aligned the same way regardless of its drawing bounds.
        return new PathIcon { Data = geometry, Width = size, Height = size };
    }
}

/// <summary>
/// XAML: <c>&lt;AppBarButton Icon="{icons:Huge Kind=Pause}" /&gt;</c>, optional <c>Size</c> (default 16).
/// </summary>
[MarkupExtensionReturnType(ReturnType = typeof(PathIcon))]
public sealed partial class HugeExtension : MarkupExtension
{
    public HugeIconKind Kind { get; set; }

    public double Size { get; set; } = 16;

    protected override object ProvideValue() => HugeIcons.Create(Kind, Size);
}
